-- Rollback for vdi-2163-md-verification-pack.sql (2026-09-05 md pass, written 2026-09-07).
-- Reverts ONLY rows this pack touched (identified by the verification_note tag) and ONLY for standard VDI-2163
-- (joined through worksheet_templates -> standards.code). The prod export taken for this pass showed all 69
-- active fields carrying the single prior status 'imported_unverified' (0 verified_against_standard,
-- 0 corrected), so every row returns to exactly that status.
-- VDI-2163 has 0 equations in prod, so there is no equations section.
-- No transaction control in this file: apply-pack.mjs supplies BEGIN/COMMIT and implements --dry-run by
-- rolling back; an inline commit would end that transaction early and turn a dry run into a real apply.

-- ---- fields (status + quote + note + verified_at) — prior status = imported_unverified (69 rows) ----
update public.fields f set verification_status='imported_unverified', verification_quote=null, verification_note=null, verified_at=null
  from public.worksheet_templates wt join public.standards s on s.id = wt.standard_id
